import type { SeedQuestion } from "./types";

/**
 * SQL bank (cap: 100).
 *
 * Every prompt here is an ORIGINAL problem written for this app against the
 * shared practice schema below. Where a published problem inspired the concept,
 * the source is cited and linked, but the wording and solution are our own.
 */

export const SQL_PRACTICE_SCHEMA = `-- Shared practice schema used by every SQL question in this bank.
users(user_id, name, email, country, signup_date, plan)
orders(order_id, user_id, order_date, amount, status)          -- status: placed|shipped|delivered|cancelled|returned
order_items(order_item_id, order_id, product_id, quantity, unit_price)
products(product_id, name, category, cost, list_price)
payments(payment_id, order_id, paid_at, amount, method)
events(event_id, user_id, event_name, event_time, device, session_id)
sessions(session_id, user_id, started_at, ended_at, platform)
employees(emp_id, name, manager_id, department, salary, hire_date)
subscriptions(sub_id, user_id, started_on, ended_on, mrr, tier)
campaigns(campaign_id, name, channel, spend, start_date, end_date)`;

type Row = [
  topic: string,
  title: string,
  difficulty: "Easy" | "Medium" | "Hard",
  minutes: number,
  frequency: number,
  patternValue: number,
  companies: string,
  skills: string,
  prompt: string,
  solution: string,
  explanation: string,
  sourceName?: string,
  sourceUrl?: string,
];

