    "WITH ordered AS (\n  SELECT session_id, user_id, event_name, event_time,\n         MIN(CASE WHEN event_name = 'product_view' THEN event_time END) OVER (PARTITION BY session_id) AS t_view,\n         MIN(CASE WHEN event_name = 'add_to_cart'  THEN event_time END) OVER (PARTITION BY session_id) AS t_cart,\n         MIN(CASE WHEN event_name = 'purchase'     THEN event_time END) OVER (PARTITION BY session_id) AS t_buy\n  FROM events\n)\nSELECT COUNT(DISTINCT session_id) FILTER (WHERE t_view IS NOT NULL) AS viewed,\n       COUNT(DISTINCT session_id) FILTER (WHERE t_cart > t_view)    AS carted,\n       COUNT(DISTINCT session_id) FILTER (WHERE t_buy  > t_cart)    AS purchased\nFROM ordered;",
