export const SQL_QUESTIONS: SeedQuestion[] = ROWS.map((r, i) => {
  const [topic, title, difficulty, minutes, frequency, patternValue, companies, skills, prompt, solution, explanation, sourceName, sourceUrl] = r;
  return {
    id: `sql-${String(i + 1).padStart(3, "0")}`,
    category: "SQL",
    topic,
    title,
    difficulty,
    estimatedMinutes: minutes,
    source: sourceName ?? "Ace the Data Science Interview",
    sourceUrl: sourceUrl ?? "https://www.acethedatascienceinterview.com",
    sourceNote:
      sourceName === "LeetCode SQL 50"
        ? "Concept drawn from the LeetCode SQL 50 study plan. Prompt and solution written for this app."
        : "Original problem written for this app against the shared practice schema, informed by common interview patterns.",
    companyTags: companies ? companies.split(",") : [],
    frequencyScore: frequency,
    patternValue,
    conceptCoverage: Math.round((frequency + patternValue) / 2),
    skillsTested: skills.split(","),
    concepts: skills.split(","),
    prompt,
    solution,
    explanation,
  };
});
